const T = 1;
const RANGES = { s1: [0, 100], s2: [-20, 80], s3: [0, 14] };

function sqlText(value) {
    return String(value).replaceAll("'", "''");
}

const text = String(msg.payload).replace(/^\uFEFF/, '');
const sql = [];

text.split(/\r?\n/).forEach(raw => {
    const line = raw.trim();
    if (!line) return;

    const parts = line.split(/\s+/);
    const kind = parts[0];
    const fields = {};
    parts.slice(1).forEach(part => {
        const separator = part.indexOf('=');
        if (separator > 0) {
            fields[part.slice(0, separator)] = part.slice(separator + 1);
        }
    });

    const n = Number.parseInt(fields.n, 10);
    if (!Number.isFinite(n)) return;
    const t = n * T;

    if (kind === 'DATA') {
        ['s1', 's2', 's3'].forEach(sensor => {
            const value = Number.parseFloat(fields[sensor]);
            if (!Number.isFinite(value)) return;

            sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${sensor}',${value});`);

            const [minValue, maxValue] = RANGES[sensor];
            if (value < minValue || value > maxValue) {
                const message = `датчик ${sensor} вне диапазона`;
                sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','${sqlText(message)}');`);
            }
        });
    } else if (kind === 'EVENT' && (fields.type === 'THRESHOLD' || fields.type === 'NORMAL')) {
        const message = fields.type === 'THRESHOLD'
            ? 'освещенность ниже 20 %'
            : 'освещенность вернулась к норме';
        sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${fields.type}','${sqlText(message)}');`);
    }
});

const head = "BEGIN;\nDELETE FROM readings;\nDELETE FROM events;\n" +
    "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n";
return [null, { payload: head + sql.join('\n') + '\nCOMMIT;\n' }];
